#pragma once

// Runtime of the generated analytic IK solvers.
//
// Code generated by CppAnalyticIkGenerator contains only a Parameters literal
// for one robot; everything else lives here. All decisions about which joint
// values come out -- the shoulder equation, the planar arm, the wrist, full
// turns within limits, singular families -- are made by the kernels in
// solver/detail/AnalyticIkKernels.hpp, shared with the general
// AnalyticIkSolver. This file only supplies geometry from the baked
// parameters and verifies forward kinematics.

#include "ik_equations/solver/detail/AnalyticIkKernels.hpp"
#include "ik_equations/solver/detail/AnalyticIkNumerics.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <numbers>
#include <numeric>
#include <optional>
#include <vector>

namespace kinemaforge::ik::generated {

struct Vec3
{
    double x{};
    double y{};
    double z{};
};

using Mat3 = std::array<std::array<double, 3>, 3>;

struct Pose
{
    Vec3 position;
    Mat3 orientation{};
};

struct Axis
{
    Vec3 point;
    Vec3 direction;
};

struct JointLimit
{
    bool enabled{};
    double lower{};
    double upper{};
};

// Everything robot-specific the generated solver needs.  No URDF, no strings,
// no expression DAG and no heap-owned model survive code generation.
struct Parameters
{
    Axis axes[6]{};
    Vec3 wristCenterHome;
    Vec3 wristInTargetFrame;
    Mat3 targetFrameHomeRotation{};

    Vec3 planarX;
    Vec3 planarY;
    double link1{};
    double link2{};
    double link2HomeAngle{};
    double axis3Sign{1.0};

    Mat3 wristBasis{};
    double axis6Sign{1.0};

    JointLimit limits[6]{};
};

enum class Status
{
    Solutions,
    NoSolution,
    InfiniteFamily,
    InvalidTarget,
    // The result would hold more branches than the caller's budget. Nothing is
    // returned; Result::requiredBranches says how many were needed.
    ResourceLimitExceeded,
    // The target lies on a singular family this solver does not parameterise:
    // the wrist centre on the joint-1 axis AND equal links folded onto the
    // joint-2 axis at once (two free joints). Solutions may well exist; this
    // is NOT NoSolution. Single free arm joints are returned as
    // positionalFamilies with status InfiniteFamily.
    UnsupportedSingularity
};

struct Branch
{
    std::array<double, 6> q{};
    bool singular{};
    // Valid only for singular wrist branches. q[3] and q[5] are NaN there;
    // q6 = dependentOffset + dependentMultiplier*q4, modulo 2*pi.
    double freeLower{};
    double freeUpper{};
    double dependentMultiplier{};
    double dependentOffset{};
};

struct Result
{
    Status status{Status::NoSolution};
    std::vector<Branch> branches; // empty for ResourceLimitExceeded
    // Branches the full result needs (upper estimate, saturated at SIZE_MAX).
    std::size_t requiredBranches{};
    // Branches reproduce the rotation NEAREST to the target orientation; this
    // is its largest element-wise distance from the orientation passed in.
    double orientationCorrection{};
    // Families with a free arm joint (wrist centre on the joint-1 axis, or
    // equal links with the elbow folded); members via evaluate(). status is
    // InfiniteFamily when any exist; `branches` may then be empty.
    std::vector<kinemaforge::ik::PositionalFamily> positionalFamilies;
};

// The member of a positional family at the given value of its free joint,
// every joint on an in-limit turn; nothing where it leaves a joint limit.
[[nodiscard]] inline std::optional<std::array<double, 6>> evaluate(const kinemaforge::ik::PositionalFamily& family,
                                                                   double value)
{
    return kinemaforge::ik::detail::evaluate(family, value);
}

namespace detail {

namespace core = ::kinemaforge::ik::detail;
namespace tolerance = ::kinemaforge::ik::tolerance;

// All thresholds come from ik_equations/model/IkTolerances.hpp, shared with
// the general solver.
inline constexpr double kLinearTolerance = tolerance::kSingularLinear;
inline constexpr double kAngularTolerance = tolerance::kSingularAngular;
inline constexpr double kOrientationTolerance = tolerance::kOrientationValidation;
inline constexpr double kTwoPi = 2.0 * std::numbers::pi_v<double>;

// --- Small vector / matrix algebra ------------------------------------------

inline Vec3 add(Vec3 a, Vec3 b) noexcept { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
inline Vec3 sub(Vec3 a, Vec3 b) noexcept { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
inline Vec3 scale(Vec3 v, double s) noexcept { return {v.x * s, v.y * s, v.z * s}; }
inline double dot(Vec3 a, Vec3 b) noexcept { return a.x * b.x + a.y * b.y + a.z * b.z; }
inline double norm(Vec3 v) noexcept { return std::hypot(v.x, v.y, v.z); }

inline Vec3 cross(Vec3 a, Vec3 b) noexcept
{
    return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
}

// Component of v perpendicular to the unit vector a.
inline Vec3 projectPerpendicular(Vec3 v, Vec3 a) noexcept
{
    return sub(v, scale(a, dot(v, a)));
}

inline Mat3 transpose(const Mat3& m) noexcept
{
    Mat3 result{};
    for (std::size_t i = 0; i < 3; ++i)
        for (std::size_t j = 0; j < 3; ++j)
            result[i][j] = m[j][i];
    return result;
}

inline Mat3 multiply(const Mat3& a, const Mat3& b) noexcept
{
    Mat3 result{};
    for (std::size_t i = 0; i < 3; ++i)
        for (std::size_t j = 0; j < 3; ++j)
            for (std::size_t k = 0; k < 3; ++k)
                result[i][j] += a[i][k] * b[k][j];
    return result;
}

inline Vec3 multiply(const Mat3& a, Vec3 v) noexcept
{
    return {a[0][0] * v.x + a[0][1] * v.y + a[0][2] * v.z,
            a[1][0] * v.x + a[1][1] * v.y + a[1][2] * v.z,
            a[2][0] * v.x + a[2][1] * v.y + a[2][2] * v.z};
}

// Rotation by angle q about the unit axis a (Rodrigues).
inline Mat3 rotation(Vec3 a, double q) noexcept
{
    const double c = std::cos(q);
    const double s = std::sin(q);
    const double t = 1.0 - c;
    return {{{c + a.x * a.x * t, a.x * a.y * t - a.z * s, a.x * a.z * t + a.y * s},
             {a.y * a.x * t + a.z * s, c + a.y * a.y * t, a.y * a.z * t - a.x * s},
             {a.z * a.x * t - a.y * s, a.z * a.y * t + a.x * s, c + a.z * a.z * t}}};
}

// Point p rotated by q about the axis line.
inline Vec3 rotatePoint(Vec3 p, const Axis& axis, double q) noexcept
{
    return add(axis.point, multiply(rotation(axis.direction, q), sub(p, axis.point)));
}

inline double normalizeAngle(double q) noexcept
{
    return core::normalizeAngle(q);
}

// --- Target validation ------------------------------------------------------

// Finite position, and an orientation that is orthonormal with determinant +1
// within kOrientationTolerance. Nothing is rewritten here; the nearest
// rotation is taken afterwards and its distance reported.
inline bool validTarget(const Pose& target) noexcept
{
    const Vec3& position = target.position;
    if (!std::isfinite(position.x) || !std::isfinite(position.y) || !std::isfinite(position.z))
        return false;
    for (const auto& row : target.orientation)
        for (double value : row)
            if (!std::isfinite(value))
                return false;

    const Mat3& m = target.orientation;
    for (std::size_t i = 0; i < 3; ++i)
        for (std::size_t j = 0; j < 3; ++j)
        {
            double columnDot = 0.0;
            for (std::size_t k = 0; k < 3; ++k)
                columnDot += m[k][i] * m[k][j];
            const double expected = i == j ? 1.0 : 0.0;
            if (std::abs(columnDot - expected) > kOrientationTolerance)
                return false;
        }

    const double determinant = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) -
                               m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) +
                               m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
    return std::abs(determinant - 1.0) <= kOrientationTolerance;
}

// --- Joint limits -----------------------------------------------------------

inline core::LimitRange range(const JointLimit& limit) noexcept
{
    return {limit.enabled, limit.lower, limit.upper};
}

inline bool withinLimit(const JointLimit& limit, double value) noexcept
{
    if (!std::isfinite(value))
        return false;
    return !limit.enabled || core::withinLimit(value, limit.lower, limit.upper);
}

// --- Geometric branches and their full turns ----------------------------------

// One geometric branch before its in-limit full turns are expanded.
struct Candidate
{
    std::array<double, 6> q{}; // q[3], q[5] unused when singular
    bool singular{};
    double multiplier{};       // singular: q6 = offset + multiplier * q4
    double offset{};
};

} // namespace detail

// Compact result: the geometric branches with, per joint, the set of its
// in-limit full turns -- its size does not depend on the width of the limits.
// expand() produces exactly the branches solve() returns.
struct CompactBranch
{
    // value(k) for k = first..last, per joint. A singular branch uses joints
    // 0, 1, 2 and 4; joints[3] and joints[5] are replaced by `family`.
    std::array<kinemaforge::ik::detail::TurnSet, 6> joints{};
    bool singular{};
    kinemaforge::ik::detail::FamilyTurns family{};

    [[nodiscard]] std::size_t count() const noexcept
    {
        std::size_t total = 1U;
        for (std::size_t i = 0; i < 6; ++i)
        {
            if (singular && (i == 3 || i == 5))
                continue;
            total = kinemaforge::ik::detail::saturatingMultiply(total, joints[i].count());
        }
        if (singular)
            total = kinemaforge::ik::detail::saturatingMultiply(total, family.count());
        return total;
    }
};

struct CompactResult
{
    // ResourceLimitExceeded only when turn numbers would not fit an int64_t.
    Status status{Status::NoSolution};
    std::vector<CompactBranch> branches;
    double orientationCorrection{};
    // As Result::positionalFamilies; not counted by expandedBranchCount().
    std::vector<kinemaforge::ik::PositionalFamily> positionalFamilies;

    [[nodiscard]] std::size_t expandedBranchCount() const noexcept
    {
        std::size_t total = 0U;
        for (const auto& branch : branches)
            total = kinemaforge::ik::detail::saturatingAdd(total, branch.count());
        return total;
    }
};

// Every branch a compact result stands for. Check expandedBranchCount() first:
// the result is a product over joints.
inline std::vector<Branch> expand(const CompactResult& compact)
{
    std::vector<Branch> output;
    constexpr double nan = std::numeric_limits<double>::quiet_NaN();
    for (const CompactBranch& branch : compact.branches)
    {
        if (branch.count() == 0U)
            continue;
        if (!branch.singular)
        {
            // Odometer over the six joints' turn numbers.
            std::array<std::int64_t, 6> turn{};
            for (std::size_t i = 0; i < 6; ++i)
                turn[i] = branch.joints[i].first;
            while (true)
            {
                Branch out;
                for (std::size_t i = 0; i < 6; ++i)
                    out.q[i] = branch.joints[i].value(turn[i]);
                output.push_back(out);

                std::size_t joint = 6;
                while (joint > 0)
                {
                    --joint;
                    if (++turn[joint] <= branch.joints[joint].last)
                        break;
                    turn[joint] = branch.joints[joint].first;
                }
                if (joint == 0 && turn[0] == branch.joints[0].first)
                    break;
            }
            continue;
        }

        const auto& j = branch.joints;
        for (auto k1 = j[0].first; k1 <= j[0].last; ++k1)
            for (auto k2 = j[1].first; k2 <= j[1].last; ++k2)
                for (auto k3 = j[2].first; k3 <= j[2].last; ++k3)
                    for (auto k5 = j[4].first; k5 <= j[4].last; ++k5)
                        for (auto k = branch.family.first; k <= branch.family.last; ++k)
                        {
                            // Free bounds and the dependent values at them lie
                            // within the limits exactly.
                            const auto interval = branch.family.interval(k);
                            if (!interval)
                                continue;
                            Branch out;
                            out.q = {j[0].value(k1), j[1].value(k2), j[2].value(k3), nan, j[4].value(k5), nan};
                            out.singular = true;
                            out.freeLower = interval->lower;
                            out.freeUpper = interval->upper;
                            out.dependentMultiplier = branch.family.multiplier;
                            out.dependentOffset = interval->offset;
                            output.push_back(out);
                        }
    }
    return output;
}

namespace detail {

// --- Forward kinematics check -----------------------------------------------

// Forward kinematics from the generated numeric parameters alone (space-axis
// product applied to the home target frame, including the TCP offset).
inline bool forwardMatches(const Parameters& p, const std::array<double, 6>& q, const Pose& target)
{
    for (double value : q)
        if (!std::isfinite(value))
            return false;

    Mat3 orientation = p.targetFrameHomeRotation;
    Vec3 position = sub(p.wristCenterHome, multiply(orientation, p.wristInTargetFrame));
    for (std::size_t i = q.size(); i-- > 0;)
    {
        const Mat3 r = rotation(p.axes[i].direction, q[i]);
        position = add(p.axes[i].point, multiply(r, sub(position, p.axes[i].point)));
        orientation = multiply(r, orientation);
    }

    const double distance = norm(sub(position, target.position));
    if (!std::isfinite(distance) || distance > tolerance::kFkPosition)
        return false;
    for (std::size_t i = 0; i < 3; ++i)
        for (std::size_t j = 0; j < 3; ++j)
        {
            const double value = orientation[i][j];
            if (!std::isfinite(value) || std::abs(value - target.orientation[i][j]) > tolerance::kFkOrientation)
                return false;
        }
    return true;
}

inline bool poseMatches(const Parameters& p, const std::array<double, 6>& q, const Pose& target)
{
    for (std::size_t i = 0; i < q.size(); ++i)
        if (!withinLimit(p.limits[i], q[i]))
            return false;
    return forwardMatches(p, q, target);
}

// A singular family is checked at both ends and the middle of its free range.
inline bool branchMatches(const Parameters& p, const Branch& branch, const Pose& target)
{
    if (!branch.singular)
        return poseMatches(p, branch.q, target);
    auto q = branch.q;
    for (double free : {branch.freeLower, std::midpoint(branch.freeLower, branch.freeUpper), branch.freeUpper})
    {
        q[3] = free;
        q[5] = branch.dependentOffset + branch.dependentMultiplier * free;
        if (!poseMatches(p, q, target))
            return false;
    }
    return true;
}

inline bool sameGeometricBranch(const std::array<double, 6>& a, const std::array<double, 6>& b) noexcept
{
    for (std::size_t i = 0; i < 6; ++i)
        if (std::abs(normalizeAngle(a[i] - b[i])) > tolerance::kSameBranch)
            return false;
    return true;
}

} // namespace detail

namespace detail {

// Phases shared by solve() and solveCompact(): validation, the shoulder, the
// arm, the wrist, and the compact turn sets of every geometric branch.
// Nothing here grows with the width of the joint limits.
struct Core
{
    CompactResult compact; // status is final unless Solutions/InfiniteFamily
    Pose target;
    bool saturated{};      // some turn numbers do not fit int64_t
};

inline Core solveCore(const Parameters& p, const Pose& requestedTarget)
{
    Core core;
    CompactResult& result = core.compact;
    if (!validTarget(requestedTarget))
    {
        result.status = Status::InvalidTarget;
        return core;
    }

    // Angles reproduce exact rotations only. Solve for the rotation nearest to
    // the accepted input and report the distance.
    const auto projected = core::nearestRotation(requestedTarget.orientation);
    if (!projected.converged || !(projected.correction <= core::kMaxOrientationCorrection))
    {
        result.status = Status::InvalidTarget;
        return core;
    }
    const Pose target{requestedTarget.position, projected.rotation};
    core.target = target;
    result.orientationCorrection = projected.correction;

    // Shoulder (q1): the wrist centre must lie in the plane swept by joint 2,
    // a*sin(q1) + b*cos(q1) = c. Infinite means the wrist centre is on the
    // joint-1 axis and q1 is free -- a family this solver does not return.
    const Vec3 targetWrist = add(target.position, multiply(target.orientation, p.wristInTargetFrame));
    const Axis& axis1 = p.axes[0];
    const Vec3 axis2Direction = p.axes[1].direction;
    const Vec3 v = sub(targetWrist, axis1.point);
    const double d1d2 = dot(axis1.direction, axis2Direction);
    const double d1v = dot(axis1.direction, v);
    const double cosCoefficient = dot(v, axis2Direction) - d1d2 * d1v;
    const double sinCoefficient = -dot(cross(axis1.direction, v), axis2Direction);
    const double constant = dot(axis1.point, axis2Direction) + d1d2 * d1v - dot(p.wristCenterHome, axis2Direction);

    const auto shoulder = core::solveSinCos(sinCoefficient, cosCoefficient, -constant, kLinearTolerance);
    if (shoulder.kind == core::SinCosKind::None)
    {
        result.status = Status::NoSolution;
        return core;
    }
    // Infinite: q1 is free. The planar target is the same for every q1, so it
    // is solved once (q1 = 0) and every arm solution seeds a q1-free family.
    const bool shoulderFamily = shoulder.kind == core::SinCosKind::Infinite;
    const std::vector<double> q1Values = shoulderFamily ? std::vector<double>{0.0} : shoulder.values;
    struct Seed
    {
        std::size_t freeJoint;
        std::array<double, 3> arm;
    };
    std::vector<Seed> seeds;

    // Geometric branches, verified and deduplicated before anything is expanded.
    std::vector<Candidate> candidates;
    const auto addRegular = [&](const std::array<double, 6>& q) {
        if (!forwardMatches(p, q, target))
            return;
        for (const auto& existing : candidates)
            if (!existing.singular && sameGeometricBranch(existing.q, q))
                return;
        Candidate candidate;
        candidate.q = q;
        candidates.push_back(candidate);
    };
    const auto addSingular = [&](double q1, double q2, double q3, double q5, double multiplier, double offset) {
        Candidate candidate;
        candidate.q = {q1, q2, q3, 0.0, q5, 0.0};
        candidate.singular = true;
        candidate.multiplier = multiplier;
        candidate.offset = offset;
        candidates.push_back(candidate);
    };

    for (double q1 : q1Values)
    {
        // Arm (q2, q3): planar 2R problem in the plane of joints 2 and 3.
        // Folded equal links: q2 is free -- reported, never one arbitrary q2.
        const Vec3 unrotated = rotatePoint(targetWrist, axis1, -q1);
        const Vec3 planarTarget = projectPerpendicular(sub(unrotated, p.axes[1].point), axis2Direction);
        const double tx = dot(planarTarget, p.planarX);
        const double ty = dot(planarTarget, p.planarY);
        const auto arm = core::solvePlanarArm(tx, ty, p.link1, p.link2, p.link2HomeAngle, p.axis3Sign,
                                              range(p.limits[2]), kLinearTolerance);
        if (arm.foldedFamily)
        {
            if (shoulderFamily)
            {
                result.status = Status::UnsupportedSingularity;
                return core;
            }
            if (!arm.branches.empty())
                seeds.push_back({1, {q1, 0.0, arm.branches.front().elbow}});
            continue;
        }
        if (shoulderFamily)
        {
            for (const auto& armBranch : arm.branches)
                seeds.push_back({0, {0.0, armBranch.shoulder, armBranch.elbow}});
            continue;
        }

        for (const auto& armBranch : arm.branches)
        {
            const double q2 = armBranch.shoulder;
            const double q3 = armBranch.elbow;

            // Wrist (q4, q5, q6): the rotation left after the first three joints,
            // expressed in the wrist basis.
            const Mat3 r123 = multiply(multiply(rotation(p.axes[0].direction, q1),
                                                rotation(p.axes[1].direction, q2)),
                                       rotation(p.axes[2].direction, q3));
            const Mat3 wristRotation = multiply(multiply(transpose(r123), target.orientation),
                                                transpose(p.targetFrameHomeRotation));
            const Mat3 local = multiply(multiply(transpose(p.wristBasis), wristRotation), p.wristBasis);
            const auto wrist = core::solveWrist(local, p.axis6Sign, range(p.limits[3]), range(p.limits[4]),
                                                range(p.limits[5]), kAngularTolerance);
            if (wrist.singular)
            {
                addSingular(q1, q2, q3, wrist.q5, wrist.multiplier, wrist.offset);
                continue;
            }
            for (const auto& w : wrist.regular)
                addRegular({q1, q2, q3, w[0], w[1], w[2]});
        }
    }

    // Compact turn sets of every geometric branch.
    for (const Candidate& candidate : candidates)
    {
        CompactBranch branch;
        branch.singular = candidate.singular;
        for (std::size_t i = 0; i < 6; ++i)
        {
            if (candidate.singular && (i == 3 || i == 5))
                continue;
            branch.joints[i] = core::turnSet(range(p.limits[i]), candidate.q[i]);
            core.saturated = core.saturated || branch.joints[i].saturated;
        }
        if (candidate.singular)
        {
            branch.family = core::familyTurns(candidate.multiplier, candidate.offset, range(p.limits[3]),
                                              range(p.limits[5]));
            core.saturated = core.saturated || branch.family.saturated;
        }
        if (branch.count() == 0U && !core.saturated)
            continue;
        result.branches.push_back(branch);
    }

    // Positional families: one per seed and wrist branch, verified with this
    // solver's own FK and limits at sample members.
    for (const Seed& seed : seeds)
        for (std::size_t wristBranch = 0; wristBranch < 2; ++wristBranch)
        {
            kinemaforge::ik::PositionalFamily family;
            family.freeJoint = seed.freeJoint;
            family.arm = seed.arm;
            family.wristBranch = wristBranch;
            for (std::size_t i = 0; i < 3; ++i)
            {
                const Vec3 axis = p.axes[i].direction;
                family.axisDirections[i] = {axis.x, axis.y, axis.z};
            }
            family.targetInHome = multiply(target.orientation, transpose(p.targetFrameHomeRotation));
            family.wristBasis = p.wristBasis;
            family.axis6Sign = p.axis6Sign;
            for (std::size_t i = 0; i < 6; ++i)
                family.limits[i] = {p.limits[i].enabled, p.limits[i].lower, p.limits[i].upper};
            const auto freeRange = core::freeParameterRange(range(p.limits[seed.freeJoint]));
            family.freeLower = freeRange.lower;
            family.freeUpper = freeRange.upper;

            constexpr int samples = 16;
            int members = 0;
            bool verified = true;
            for (int step = 0; step <= samples && verified; ++step)
            {
                const double value = std::lerp(family.freeLower, family.freeUpper,
                                               static_cast<double>(step) / samples);
                const auto member = core::evaluate(family, value);
                if (!member)
                    continue;
                ++members;
                verified = poseMatches(p, *member, target);
            }
            if (verified && members > 0)
                result.positionalFamilies.push_back(family);
        }

    if (result.branches.empty() && result.positionalFamilies.empty())
    {
        result.status = Status::NoSolution;
        return core;
    }
    const bool family = !result.positionalFamilies.empty() ||
                        std::any_of(result.branches.begin(), result.branches.end(),
                                    [](const CompactBranch& branch) { return branch.singular; });
    result.status = family ? Status::InfiniteFamily : Status::Solutions;
    return core;
}

} // namespace detail

// All solutions in compact form; no branch budget is needed.
inline CompactResult solveCompact(const Parameters& p, const Pose& target)
{
    auto core = detail::solveCore(p, target);
    if (core.saturated)
    {
        core.compact.status = Status::ResourceLimitExceeded;
        core.compact.branches.clear();
    }
    return core.compact;
}

// maxBranches bounds the number of branches (regular solutions and singular
// families) in one result. Every in-limit full turn of every joint is a
// separate branch, so the count is a product over joints; it is computed from
// the compact form before anything is allocated. A result that would exceed
// the bound is reported as ResourceLimitExceeded and never truncated (see
// solveCompact() for limits too wide to expand).
inline Result solve(const Parameters& p, const Pose& requestedTarget, std::size_t maxBranches = 4096)
{
    using namespace detail;
    const Core core = solveCore(p, requestedTarget);
    Result result;
    result.orientationCorrection = core.compact.orientationCorrection;
    result.status = core.compact.status;
    result.positionalFamilies = core.compact.positionalFamilies;
    if (core.compact.branches.empty())
        return result;

    result.requiredBranches = core.saturated ? std::numeric_limits<std::size_t>::max()
                                             : core.compact.expandedBranchCount();
    if (core::branchBudgetExceeded(result.requiredBranches, maxBranches))
    {
        result.status = Status::ResourceLimitExceeded;
        return result;
    }

    // Expand, then verify every branch that is returned.
    result.branches = expand(core.compact);
    std::erase_if(result.branches, [&](const Branch& branch) { return !branchMatches(p, branch, core.target); });
    if (result.branches.empty() && result.positionalFamilies.empty())
    {
        result.status = Status::NoSolution;
        return result;
    }
    const bool family = !result.positionalFamilies.empty() ||
                        std::any_of(result.branches.begin(), result.branches.end(),
                                    [](const Branch& branch) { return branch.singular; });
    result.status = family ? Status::InfiniteFamily : Status::Solutions;
    return result;
}

} // namespace kinemaforge::ik::generated
